INSERT INTO forms (slug,title,event,fields,active,created_at,updated_at) VALUES ('register-2026','Register for COhere 2026','october2026','[{"key":"full_name","label":"Full name","label_es":"Nombre completo","type":"text","required":true},{"key":"email","label":"Email","label_es":"Correo","type":"email","required":true,"help":"We''ll send your confirmation here."},{"key":"phone","label":"Phone (optional)","type":"tel"},{"key":"volunteer_interest","label":"Are you interested in volunteering?","label_es":"¿Te interesa ser voluntario/a?","help":"We''ll email you with more info.","type":"radio","options":["Yes","No","Maybe"],"options_es":["Sí","No","Quizá"],"allow_other":true},{"key":"interests","label":"What are you drawn to?","type":"checkboxes","options":["Food & land","Music","Healing","Building","Kids & elders"]},{"key":"notes","label":"Anything else we should know?","type":"textarea"},{"key":"subscribed","label":"Send me updates about COhere","type":"checkbox","default":true}]',1,datetime('now'),datetime('now')) ON CONFLICT(slug) DO UPDATE SET fields=excluded.fields,active=1;